local Players = game:GetService("Players")
local StarterGui = game:GetService("StarterGui")
local LocalPlayer = Players.LocalPlayer


local function sendNotify(title, text)
    pcall(function()
        StarterGui:SetCore("SendNotification", {
            Title = title,
            Text = text,
            Duration = 5
        })
    end)
    print("[" .. title .. "] " .. text)
end


if not hookmetamethod or not getnamecallmethod then 
    return sendNotify('Incompatible Exploit', 'Your executor lacks hookmetamethod support.')
end

local oldhmmi
local oldhmmnc
local oldKickFunction


if hookfunction then
    oldKickFunction = hookfunction(LocalPlayer.Kick, function() end)
end


oldhmmi = hookmetamethod(game, "__index", function(self, method)
    if self == LocalPlayer and tostring(method):lower() == "kick" then
        return function() end
    end
    return oldhmmi(self, method)
end)


oldhmmnc = hookmetamethod(game, "__namecall", function(self, ...)
    if self == LocalPlayer and getnamecallmethod():lower() == "kick" then
        return
    end
    return oldhmmnc(self, ...)
end)


